    u32 capacity = end - start + 1;
    CIrConstantInitializerTask* tasks = arena_allocate(task_arena, CIrConstantInitializerTask, capacity);
    u32 task_count = 1;
    tasks[0] = (CIrConstantInitializerTask){
        .type = root_type,
        .start = start,
        .end = end,
    };
